"""
Runs tools/benchmark_collisions.bb with the broad phase of the collisions (the default) and without it
(BLITZLLVM_COLLISION_BROADPHASE=0), for several amounts of statics and movers, and prints milliseconds per UpdateWorld.

    python3 tools/benchmark_collisions.py [path to blitzcc] [statics:movers:method ...]

Without a display the programs run under xvfb-run.
"""
import os
import re
import shutil
import subprocess
import sys
import tempfile
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "."))
import procutil  # noqa: E402


def main():
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    args = sys.argv[1:]
    compiler = args.pop(0) if args and os.path.isfile(args[0]) else os.path.join(root, "build", "code_compiler", "blitzcc")
    cases = [tuple(int(v) for v in a.split(":")) for a in args] or [(1000, 100, 2), (5000, 200, 2), (5000, 200, 3), (5000, 200, 1)]
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") else ["xvfb-run", "-a"]
    if runner and not shutil.which("xvfb-run"):
        sys.exit("There is no display and no xvfb-run.")
    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "benchmark")
        procutil.run([compiler, os.path.join(root, "tools", "benchmark_collisions.bb"), "-o", program], check=True, stdout=subprocess.DEVNULL)
        print("%-8s %-8s %-7s %12s %12s %9s" % ("statics", "movers", "method", "broad ms", "brute ms", "gain"))
        for statics, movers, method in cases:
            results = {}
            for mode in ("broad", "brute"):
                env = dict(os.environ, BENCH_STATICS=str(statics), BENCH_MOVERS=str(movers), BENCH_METHOD=str(method))
                env.pop("BLITZLLVM_COLLISION_BROADPHASE", None)
                if mode == "brute":
                    env["BLITZLLVM_COLLISION_BROADPHASE"] = "0"
                run = procutil.run(runner + [program], env=env, capture_output=True, text=True)
                found = re.search(r"update_ms=([0-9.]+)", run.stdout + run.stderr)
                results[mode] = float(found.group(1)) if found else float("nan")
            print("%-8d %-8d %-7d %12.2f %12.2f %8.1fx" % (statics, movers, method, results["broad"], results["brute"], results["brute"] / results["broad"]))


main()
